"""Loaders for shaft-calcium disc traces."""

from __future__ import annotations

import xarray as xr

import wisco_slap as wis
from wisco_slap.pns.shaft_ca_gen import shaft_ca_dir


def shaft_ca(
    subject: str,
    exp: str,
    loc: str,
    acq: str,
    dmd: int | None = None,
    apply_ephys_offset: bool = True,
) -> dict[str, xr.Dataset]:
    """Load shaft-calcium disc traces generated by ``wis.pns.shaft_ca_gen``.

    Parameters
    ----------
    subject, exp, loc, acq : str
        Acquisition identifiers.
    dmd : int or None
        DMD number (1 or 2). None loads every DMD with an output.
    apply_ephys_offset : bool
        If True (default), shift the ``time`` coordinate by the acquisition's
        ephys offset so times align with the ephys/sync-block clock, matching
        the behavior of the scopex loaders.

    Returns
    -------
    dict[str, xr.Dataset]
        ``{"dmd_1": Dataset, ...}`` with ``F``/``dff`` (disc x time), disc
        coords (``dendrite_id``, ``arc_um``, ``F0``, ...), and per-frame
        ``trial``/``quality`` coords.
    """

    directory = shaft_ca_dir(subject, exp, loc, acq)
    dmds = [dmd] if dmd is not None else [1, 2]
    out: dict[str, xr.Dataset] = {}
    offset = (
        wis.meta.get.ephys_offset(subject, exp, loc, acq)
        if apply_ephys_offset
        else 0.0
    )
    for d in dmds:
        path = directory / f"shaft_ca_dmd{d}.zarr"
        if not path.is_dir():
            if dmd is not None:
                raise FileNotFoundError(f"No shaft-calcium output at {path}")
            continue
        dataset = xr.open_zarr(path).load()
        if apply_ephys_offset:
            # time ticks on the microscope clock (~4 ppm slow vs TDT); convert
            # to TDT seconds before anchoring, matching the scopex loaders
            ratio = wis.meta.get.clock_ratio(subject, exp, loc, acq)
            dataset = dataset.assign_coords(
                time=dataset["time"] / ratio + float(offset)
            )
        out[f"dmd_{d}"] = dataset
    if not out:
        raise FileNotFoundError(
            f"No shaft-calcium outputs in {directory}; run "
            "wis.pns.shaft_ca_mon.acq_data(...) first"
        )
    return out
